# import necessary packages
import math

# all class and function definitions in the code file, if any
class Book(object):
    def __init__(self, book, author, nbrPage):
        self.book = book
        self.author = author
        self.nbrPage = nbrPage
        self.currPage = 1
        self.bookMark = None

    def __repr__(self):
        if self.nbrPage == 1 or self.nbrPage == 0:
            return f"Book<{self.book} by {self.author}: {self.nbrPage} page, currently on page {self.currPage}>"
        elif self.bookMark is not None:
            return f"Book<{self.book} by {self.author}: {self.nbrPage} pages, currently on page {self.currPage}, page {self.bookMark} bookmarked>"
        else:
            return f"Book<{self.book} by {self.author}: {self.nbrPage} pages, currently on page {self.currPage}>"

    def turnPage(self, pageTurn):
        self.currPage += pageTurn
        if self.currPage < 1:
            self.currPage = 1
        if self.currPage > self.nbrPage:
            self.currPage = self.nbrPage

    def getCurrentPage(self):
        return self.currPage

    def getBookmarkedPage(self):
        return self.bookMark

    def placeBookmark(self):
        self.bookMark = self.currPage

    def turnToBookmark(self):
        if self.bookMark is not None:
            self.currPage = self.bookMark

    def removeBookmark(self):
        self.bookMark = None

    def __eq__(self, other):
        return (self.book == other.book and self.author == other.author and
                self.nbrPage == other.nbrPage and self.currPage == other.currPage and
                self.bookMark == other.bookMark)

# main function
def main_solution(book_title, author, nbr_pages, page_turns):
    # Create a Book object
    book = Book(book_title, author, nbr_pages)

    # Turn pages as specified
