    x = u * np.cos(lon)
    y = u * np.sin(lon)
    return x, y, z

def great_circle_dist(lat1, lon1, lat2, lon2):
    R = 6.371 * 10**6
    lat1 = lat1 / 180 * math.pi
    lon1 = lon1 / 180 * math.pi
    lat2 = lat2 / 180 * math.pi
    lon2 = lon2 / 180 * math.pi
    temp = np.cos(lat1) * np.cos(lat2) * np.cos(lon1 - lon2) + np.sin(lat1) * np.sin(lat2)
    if isinstance(temp, np.ndarray):
        temp[temp > 1] = 1
        temp[temp < -1] = -1
    else:
        if temp > 1:
            temp = 1
        if temp < -1:
            temp = -1
    theta = np.arccos(temp)
    d = theta * R
    return d

def shortest_dist_to_great_circle(lat, lon, lat_start, lon_start, lat_end, lon_end):
    R = 6.371 * 10**6
    if abs(lat_start - lat_end) < 1e-6 and abs(lon_start - lon_end) < 1e-6:
        return np.zeros(len(lat))
    else:
        x, y, z = cartesian(lat, lon)
        x_start, y_start, z_start = cartesian(lat_start, lon_start)
        x_end, y_end, z_end = cartesian(lat_end, lon_end)
        cross_product = np.cross(np.array([x_start, y_start, z_start]), np.array([x_end, y_end, z_end]))
        N = cross_product / (np.linalg.norm(cross_product) + 1e-6)
        C = np.array([x, y, z]) / R
        temp = np.dot(N, C)
        if isinstance(temp, np.ndarray):
            temp[temp > 1] = 1
            temp[temp < -1] = -1
        else:
            if temp > 1:
                temp = 1
            if temp < -1:
                temp = -1
        NOC = np.arccos(temp)
        d = abs(math.pi / 2 - NOC) * R
        return d

def pairwise_great_circle_dist(latlon_array):
    dist = []
    k = np.shape(latlon_array)[0]
    for i in range(k - 1):
        for j in np.arange(i + 1, k):
            dist.append(great_circle_dist(latlon_array[i, 0], latlon_array[i, 1], latlon_array[j, 0], latlon_array[j, 1]))
    return dist

# main function
def main_solution(latlon_array, threshold_distance):
    """
    Args:
        latlon_array (list of lists): A list of latitude and longitude pairs. Each pair is a list with two elements: [latitude, longitude].
        threshold_distance (float): The threshold distance in meters to determine if a knot exists.

    Returns:
        dict: A dictionary with two keys:
            - 'knot_exists' (int): 1 if a knot exists, 0 otherwise.
            - 'knot_position' (int or None): The index of the knot if it exists, None otherwise.
    """
    latlon_array = np.array(latlon_array)
    n = latlon_array.shape[0]
    if n > 1:
        lat_start = latlon_array[0, 0]
        lon_start = latlon_array[0, 1]
        lat_end = latlon_array[-1, 0]
        lon_end = latlon_array[-1, 1]
        lat = latlon_array[:, 0]
        lon = latlon_array[:, 1]
        d = shortest_dist_to_great_circle(lat, lon, lat_start, lon_start, lat_end, lon_end)
        if max(d) < threshold_distance:
            return {'knot_exists': 0, 'knot_position': None}
        else:
            return {'knot_exists': 1, 'knot_position': int(np.argmax(d))}
    else:
        return {'knot_exists': 0, 'knot_position': None}

